#include <stdio.h>

int main(void) {
    int dem = 0;
    for (int i = 0; i < 4; i++) {
        unsigned int trang_thai;
        if (scanf("%x", &trang_thai) != 1) return 1;
        if (trang_thai == 0x80) dem++;
    }
    printf("%d\n", dem);
    return 0;
}
